<?php
trait CxStockAlerts {
    public function saveStockPolicy($company,array $p) {
        $this->operational($company,'ALMACEN');$warehouse=$this->reference($company,'ALMACEN',$p['idAlmacen']??0);$m=$this->material($company,$p['idProducto']??0);$min=cxDec($p['minimo']??'',2);$target=cxDec($p['objetivo']??'',2);if(bccomp($target,$min,4)<0)throw new CxError('El stock objetivo debe ser igual o mayor al mínimo.');$days=$p['diasReposicion']??null;if(filter_var($days,FILTER_VALIDATE_INT)===false||(int)$days<0||(int)$days>365)throw new CxError('El plazo de reposición debe estar entre 0 y 365 días.');$reason=cxText($p['motivo']??'',1000,true);
        return $this->atomic($company,function()use($company,$warehouse,$m,$min,$target,$days,$reason){$old=$this->run('SELECT * FROM Cx_StockPolitica WHERE IdEmpresa=? AND IdAlmacen=? AND IdProducto=?',[$company,$warehouse,$m['IdProducto']])->fetch(PDO::FETCH_ASSOC);$this->run('INSERT INTO Cx_StockPolitica(IdEmpresa,IdAlmacen,IdProducto,Minimo,Objetivo,DiasReposicion,UsuarioMod,FechaMod) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE Minimo=VALUES(Minimo),Objetivo=VALUES(Objetivo),DiasReposicion=VALUES(DiasReposicion),UsuarioMod=VALUES(UsuarioMod),FechaMod=VALUES(FechaMod)',[$company,$warehouse,$m['IdProducto'],$min,$target,(int)$days,$this->user,cxNow()]);$this->audit($company,'stock-politica',$m['IdProducto'],'CONFIGURAR',$old?:null,['almacen'=>$warehouse,'minimo'=>$min,'objetivo'=>$target,'dias'=>$days],$reason);return ['ok'=>true];});
    }
    public function stockAlerts($company,$warehouse,$until) {
        $this->permission($company);$warehouse=$this->reference($company,'ALMACEN',$warehouse);$until=cxDate($until);$policies=$this->run('SELECT * FROM Cx_StockPolitica WHERE IdEmpresa=? AND IdAlmacen=?',[$company,$warehouse])->fetchAll(PDO::FETCH_ASSOC);$policy=[];foreach($policies as $p)$policy[$p['IdProducto']]=$p;
        $plans=$this->run("SELECT p.*,o.Anio AS PedidoAnio,o.Numero AS PedidoNumero FROM Cx_Programacion p JOIN Cx_Pedido o ON o.IdEmpresa=p.IdEmpresa AND o.IdPedido=p.IdPedido WHERE p.IdEmpresa=? AND p.IdAlmacen=? AND p.Estado IN ('BORRADOR','CONFIRMADA') AND p.Inicio<=? ORDER BY p.Inicio,p.IdProgramacion",[$company,$warehouse,$until.' 23:59:59'])->fetchAll(PDO::FETCH_ASSOC);
        $by=[];$unknown=[];foreach($plans as $plan){if(!$plan['IdDisenoVersion']){$unknown[]=['id'=>$plan['IdProgramacion'],'pedido'=>$plan['PedidoAnio'].'-'.$plan['PedidoNumero'],'motivo'=>'Sin receta: no se puede calcular el requerimiento.'];continue;}$d=$this->design($company,$plan['IdDisenoVersion']);if($d['Estado']!=='APROBADA')$unknown[]=['id'=>$plan['IdProgramacion'],'pedido'=>$plan['PedidoAnio'].'-'.$plan['PedidoNumero'],'motivo'=>'Receta no aprobada: requerimiento provisional.'];foreach($d['componentes'] as $c){$by[$c['IdProducto']][]=['id'=>$plan['IdProgramacion'],'pedido'=>'PW-'.$plan['PedidoAnio'].'-'.str_pad($plan['PedidoNumero'],5,'0',STR_PAD_LEFT),'inicio'=>$plan['Inicio'],'estado'=>$plan['Estado'],'cantidad'=>bcmul($c['CantidadNominal'],$plan['Cantidad'],6),'receta'=>$d['Codigo'].' v'.$d['Version'],'provisional'=>$d['Estado']!=='APROBADA'];}}
        $rows=$this->materials($company,$warehouse);foreach($rows as &$m){$p=$policy[$m['IdProducto']]??null;$sources=$by[$m['IdProducto']]??[];$draft='0';foreach($sources as $s)if($s['estado']==='BORRADOR')$draft=bcadd($draft,$s['cantidad'],6);$demand=bcadd($m['stock']['reservadoNominal'],$draft,6);$projected=bcsub($m['stock']['fisico'],$demand,6);$short=bccomp($projected,'0',6)<0?bcsub('0',$projected,6):'0';$low=$p&&bccomp($projected,$p['Minimo'],6)<=0;$buy=bccomp($short,'0',6)>0||$low?bcsub($p?$p['Objetivo']:'0',$projected,6):'0';if(bccomp($buy,'0',6)<0)$buy='0';$deadline=null;if($p&&$sources){$deadline=(new DateTimeImmutable($sources[0]['inicio'],new DateTimeZone('America/Lima')))->modify('-'.$p['DiasReposicion'].' days')->format('Y-m-d H:i:s');}
            $m['politica']=$p;$m['demandaBorrador']=bcadd($draft,'0',6);$m['requeridoNominal']=$demand;$m['saldoProyectado']=$projected;$m['faltante']=$short;$m['compraSugerida']=$buy;$m['comprarAntes']=$deadline;$m['estado']=bccomp($short,'0',6)>0?'FALTANTE':($low?'REPOSICION':($p?'SUFICIENTE':'SIN_MINIMO'));$m['origen']=$sources;
        }unset($m);return ['consultadoEn'=>cxNow(),'hasta'=>$until,'idAlmacen'=>$warehouse,'materiales'=>$rows,'programacionesSinValidar'=>$unknown,'criterio'=>'Stock físico actual menos reservas confirmadas de todas las fechas y borradores hasta la fecha elegida. No considera compras todavía no recibidas ni consumos reales futuros.'];
    }
}
